  const frameworkRefs = lib.xmlElements(text, 'FrameworkReference').map(e => e.attrs.Include || '');
  return { rel, name: path.posix.basename(rel).replace(/\.(cs|fs|vb)proj$/i, ''), sdk, packages, projectRefs, frameworkRefs };
